      "ho_id": "HO2",
      "meaningful_trajectory_impact": false,
      "triggered": false
    },
    {
      "active_model_action": false,
      "citations": [],
      "completion": "not_triggered",
      "explanation": "HO3 was not triggered because there was no early drift to repair; the doctor's first message was already a generic plan that did not correct course later.",
      "ho_id": "HO3",
